UPDATE "page" SET "corps_md" = replace(replace(replace(replace(replace(replace(replace(replace("corps_md", 'AMELIORATION', 'AMÉLIORATION'), 'CADAVERIQUE', 'CADAVÉRIQUE'), 's magique d', 's magiques d'), 's divisé p', 's divisés p'), 's physique d', 's physiques d'), ' divisé ', ' divisés '), 'VItesse', 'Vitesse'), 'sacrifié', 'sacrifier') WHERE id = 'bestiaire/animation-des-morts';
